-- Pre-existing regulator g-rule, so the "removed at login" scenario has something to remove.
INSERT INTO dbo.casbin_rule (ptype, v0, v1, v2)
SELECT 'g', 'user0b000000-0000-0000-0000-000000000511', 'role' + CAST(r.id AS varchar(20)), N'Project' FROM dbo.roles r WHERE r.name = N'regulator of project' AND r.deleted_at IS NULL
AND NOT EXISTS (SELECT 1 FROM dbo.casbin_rule c WHERE c.ptype = 'g' AND c.v0 = 'user0b000000-0000-0000-0000-000000000511' AND c.v1 = 'role' + CAST(r.id AS varchar(20)));

